/**
 * @amc/vnexus: the pure core of VNEXUS ACE, a TypeScript twin of
 * `services/langgraph/agency/vnexus` (genome, temporal graph, multiverse, immune
 * checks, marketing arithmetic, art-director scoring, prompt-genome helpers).
 *
 * Python stays the reference. `tests/fixtures/vnexus-core-parity.json` is generated by
 * `services/langgraph/tests/test_vnexus_core_parity_fixture.py` and every case must be
 * reproduced exactly by `tests/parity.test.ts`. Persistence, approvals, routes, PIL and
 * renderers stay in Python.
 *
 * Divergences, each refused or recorded in the fixture rather than guessed at:
 * - Pydantic lax mode (numeric strings, bool as int, integral floats for int fields)
 *   is refused; the fixture lists each as "Python accepts, TS refuses".
 * - An integral float must be a `CanonicalFloat`; an integral `number` is a Python int.
 * - Integers beyond 2^53 are refused.
 * - `Math.pow`/`Math.log` are not bit-identical to the C library's: the sRGB table comes
 *   from Python, the cube root and the logarithm are computed correctly rounded.
 * - `history()` refuses a supersession cycle where Python would loop forever.
 */
export { CanonicalFloat } from '@amc/canonical';
export * from './errors';
export * from './genome';
export * from './resolve';
export * from './graph';
export * from './multiverse';
export * from './immune';
export * from './marketing';
export * from './artdirector';
export * from './promptgenome';
export { deltaE76, wcagContrastRatio, relativeLuminance, colorsIn, powThird } from './color';
export { log, normalInvCdf } from './mathx';
export type { PyData, PyFloatValue } from './python';
